import {keyName,formatSeconds,correctAnswer,validateLevel,scoreMatch,soloSummary} from './core.js';
import {esc,editorSvg} from './renderer.js';
const button=(action,text,attrs='',primary=false)=>`<button class="action ${primary?'primary':''}" data-action="${action}" ${attrs}>${text}</button>`;
const options=(items,selected)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('');
const field=(name,title,content)=>`<label class="form-field" for="${name}"><span>${title}</span>${content}</label>`;
export function availableLevels(ctx){return [...ctx.pack.levels.map((l,i)=>({key:`reference:${i}`,label:`Reference · ${i+1}. ${l.name}`,level:l})),...ctx.store.levels.map(l=>({key:`saved:${l.id}`,label:`My levels · ${l.name}`,level:l})),...ctx.store.packs.flatMap(p=>p.levels.map((l,i)=>({key:`pack:${p.id}:${i}`,label:`${p.title} · ${i+1}. ${l.name}`,level:l})))];}
export function renderUI(ctx){
  const {screen,store,ui,engine,pack}=ctx,b=store.settings.bindings;
  if(screen==='menu')return {cls:'active menu complete-menu',html:`<div class="menu-panel"><p class="eyebrow">Two players · one keyboard</p><h1>Count what<br>you saw.</h1><p class="intro">Remember the boxes. Tally your answer. A mistake adds five seconds; the lower total time wins.</p><div class="mode-grid">
    ${[['classic','Classic','10 researched rounds'],['quick','Quick match','5 fresh puzzles'],['full','Full match','20 fresh puzzles'],['endless','Endless practice','Keep going at your pace'],['practice','Choose a puzzle','Practice any saved level'],['custom','Custom match','Choose your rules and pack']].map(([mode,title,copy])=>`<button class="mode-card ${mode==='classic'?'featured':''}" data-action="mode" data-mode="${mode}"><strong>${title}</strong><span>${copy}</span></button>`).join('')}
    </div><div class="key-legend"><span>P1 <kbd>${esc(keyName(b.p1Count))}</kbd> count <kbd>${esc(keyName(b.p1Submit))}</kbd> done</span><span>P2 <kbd>${esc(keyName(b.p2Count))}</kbd> count <kbd>${esc(keyName(b.p2Submit))}</kbd> done</span></div><div class="menu-links">${button('editor','Create a level')}${button('library','My levels and packs')}${button('history','Match history')}${button('help','How to play')}</div></div>`};
  if(screen==='setup'){
    const c=ui.setup,mode=c.mode,names={quick:'Quick match',full:'Full match',endless:'Endless practice',practice:'Choose a puzzle',custom:'Custom match'};
    return {cls:'active form-screen',html:`<div class="form-panel"><p class="eyebrow">Choose the challenge</p><h2>${names[mode]}</h2><form id="setup-form"><div class="form-grid">
      ${mode==='endless'||mode==='practice'?'':field('players','Players',`<select id="players" name="players">${options([['2','Two players'],['1','Solo']],c.players)}</select>`)}
      ${mode==='practice'?field('practiceLevel','Puzzle',`<select id="practiceLevel" name="practiceLevel">${options(availableLevels(ctx).map(l=>[l.key,l.label]),c.practiceLevel)}</select>`):''}
      ${mode==='custom'?field('source','Puzzle source',`<select id="source" name="source">${options([['generated','Fresh generated puzzles'],['reference','Reference pack'],...store.packs.map(p=>[`pack:${p.id}`,p.title])],c.source)}</select>`):''}
      ${mode==='custom'?field('rounds','Number of rounds',`<input id="rounds" name="rounds" type="number" min="1" max="50" value="${c.rounds}" required>`):''}
      ${mode==='practice'?'':field('difficulty','Difficulty',`<select id="difficulty" name="difficulty">${options([['gentle','Gentle'],['standard','Standard'],['intense','Intense']],c.difficulty)}</select>`)}
      ${mode==='endless'?field('family','Puzzle style',`<select id="family" name="family">${options([['mixed','A mix of styles'],['cluster','Grouped boxes'],['scattered','Scattered boxes'],['towers','Towers'],['large','Large and small'],['travel','Travelling boxes'],['flash','Quick flashes'],['dense','Full boards']],c.family)}</select>`):''}
      ${mode==='practice'?'':field('seed','Puzzle seed',`<input id="seed" name="seed" maxlength="80" value="${esc(c.seed)}" required>`)}
      ${field('previewMs','Viewing time',`<select id="previewMs" name="previewMs">${options([['0','Use each puzzle’s timing'],['750','0.75 seconds'],['1500','1.5 seconds'],['2500','2.5 seconds'],['5000','5 seconds']],c.previewMs)}</select>`)}
      ${mode==='custom'?field('answerLimitMs','Answer limit',`<select id="answerLimitMs" name="answerLimitMs">${options([['0','Wait until everyone submits'],['5000','5 seconds'],['8000','8 seconds'],['15000','15 seconds'],['30000','30 seconds']],c.answerLimitMs)}</select>`):''}
    </div>${mode==='custom'?`<label class="check-label"><input name="shuffle" type="checkbox" ${c.shuffle?'checked':''}> Shuffle an authored pack</label><p class="small-copy">Authored packs play once through. The round count applies to generated puzzles.</p>`:''}<p class="small-copy">A large, unsegmented box counts as one. Separate boxes in a tower each count. The same seed and settings reproduce the generated puzzles.</p><div class="actions">${button('submit-setup','Check controls','type="submit"',true)}${button('menu','Back','type="button"')}</div></form></div>`};
  }
  if(screen==='checks'){
    const checkPlayer=p=>`<div class="check-player"><h3><span class="color-pip ${p?'p2':''}"></span>Player ${p+1}</h3>${[0,1].map(a=>`<div class="check-row"><span>Press <kbd>${esc(keyName(b[`${p?'p2':'p1'}${a?'Submit':'Count'}`]))}</kbd> ${a?'to submit':'to count'}</span><span class="checkmark ${ui.checked[p*2+a]?'done':''}">${ui.checked[p*2+a]?'✓':'○'}</span></div>`).join('')}</div>`;
    const ready=ui.checked[0]&&ui.checked[1]&&(ui.config.solo||ui.checked[2]&&ui.checked[3]);
    return {cls:'active check',html:`<div class="check-panel"><p class="eyebrow">${esc(ui.config.label)}</p><h2>Check your keys</h2><p class="panel-copy">Tap your count key and submit key. Each press adds one; holding never repeats.</p><div class="check-grid">${checkPlayer(0)}${ui.config.solo?'':checkPlayer(1)}</div><div class="actions center-actions">${button('start','Start counting',ready?'':'disabled',true)}${button('settings','Change controls')}${button('menu','Back')}</div></div>`};
  }
  if(screen==='paused')return {cls:'active paused',html:`<div class="pause-panel"><p class="eyebrow">Game paused</p><h2>Take your time</h2><p class="panel-copy">Finished rounds keep their times. An interrupted puzzle restarts with a replacement${engine.config.source==='authored'?'; authored puzzles restart as assisted practice':''}.</p><div class="actions center-actions">${button('resume','Resume','',true)}${engine.config.endless?button('finish-practice','Finish practice'):''}${button('menu','Leave session')}</div></div>`};
  if(screen==='results'){
    const result=engine.result(),solo=engine.config.solo;
    const cols=solo?`<div class="solo-stat-grid"><div><strong>${result.correct} / ${result.total}</strong><span>Correct answers</span></div><div><strong>${result.accuracy}%</strong><span>Accuracy</span></div><div><strong>${formatSeconds(result.total?result.rawMs/result.total:0)}s</strong><span>Average answer time</span></div></div>`:[0,1].map(i=>{const p=result.players[i];return `<div class="result-player ${i?'p2':''}"><h3>Player ${i+1}</h3><div class="result-status ${result.winner!==i?'other':''}">${result.winner===null?'Draw':result.winner===i?'Winner':'Runner up'}</div><div class="result-line"><span>Answer time</span><strong>${formatSeconds(p.rawMs)} sec</strong></div><div class="result-line"><span>Mistakes</span><strong>${p.mistakes} × 5 sec</strong></div><div class="result-line"><span>Penalty</span><strong>+${formatSeconds(p.penaltyMs)} sec</strong></div><div class="result-line total"><span>Total</span><span>${formatSeconds(p.adjustedMs)} sec</span></div></div>`;}).join('');
    return {cls:'active result scroll-screen',html:`<div class="result-panel"><p class="eyebrow">${esc(engine.config.label)} · ${engine.rounds.length} rounds complete${engine.assisted?' · assisted':''}</p><h2>${solo?'Practice complete':result.winner===null?'It’s a draw.':`Player ${result.winner+1} wins.`}</h2><div class="${solo?'':'result-grid'}">${cols}</div><div class="actions center-actions">${button('again',engine.config.endless?'Practice again':'Play again','',true)}${button('details','Round details')}${ui.returnTo==='editor'?button('return-editor','Back to editor'):ui.returnTo==='library'?button('return-library','Back to library'):ui.returnTo==='history'?button('return-history','Back to history'):''}${button('menu','Main menu')}</div></div>`};
  }
  if(screen==='settings')return {cls:'active form-screen',html:`<div class="form-panel"><p class="eyebrow">Make it comfortable</p><h2>Settings</h2><div class="settings-controls"><h3>Keyboard controls</h3><p class="small-copy">Click a key, then press its replacement. Each action needs a different key.</p><div class="binding-grid">${Object.keys(b).map((k,i)=>`<div><span>Player ${i<2?1:2} ${i%2?'submit':'count'}</span>${button('bind',ui.captureKey===k?'Press a key…':esc(keyName(b[k])),`data-key="${k}"`)}</div>`).join('')}</div><div class="actions">${button('default-keys','Z / X and N / M')}${button('alternate-keys','A / S and K / L')}</div></div><form id="settings-form"><div class="settings-options"><label class="check-label"><input name="sound" type="checkbox" ${store.settings.sound?'checked':''}> Sound effects</label>${field('volume','Volume',`<input id="volume" name="volume" type="range" min="0" max="1" step="0.05" value="${store.settings.volume}">`)}<label class="check-label"><input name="highContrast" type="checkbox" ${store.settings.highContrast?'checked':''}> Higher contrast</label><label class="check-label"><input name="reducedMotion" type="checkbox" ${store.settings.reducedMotion?'checked':''}> Replace travelling puzzles with stationary views</label><p class="small-copy">Changing motion marks the session as assisted. Audio cues are optional.</p></div><div class="actions">${button('save-settings','Save settings','type="submit"',true)}${button('settings-back','Back','type="button"')}</div></form></div>`};
  if(screen==='editor'){
    const e=ui.editor,l=e.level,selected=l.boxes.find(b=>b.id===e.selected),errors=validateLevel(l),volume=l.boxes.reduce((n,b)=>n+b.w*b.d*b.h,0);
    const properties=['x','y','z','w','d','h'].map(k=>field(`box-${k}`,({x:'X cell',y:'Y cell',z:'Bottom height',w:'Width',d:'Depth',h:'Height'})[k],`<input id="box-${k}" type="number" min="${['w','d','h'].includes(k)?1:0}" max="${k==='z'?3:['h'].includes(k)?4:5}" value="${selected?.[k]??(['w','d','h'].includes(k)?1:0)}">`)).join('');
    return {cls:'active editor-screen',html:`<div class="editor-panel"><div class="page-top"><div><p class="eyebrow">Create your own challenge</p><h2>Level editor</h2></div>${button('library','My library')}</div><div class="editor-layout"><div class="editor-left"><div class="editor-tools">${['add','select','delete'].map(tool=>button('editor-tool',tool==='add'?'Add box':tool==='select'?'Select':'Delete',`data-tool="${tool}" aria-pressed="${e.tool===tool}"`)).join('')}</div><svg id="editor-board" viewBox="0 0 1280 720" role="img" aria-label="Editable isometric box board">${editorSvg(l,e.selected,store.settings)}</svg><div class="editor-summary"><strong>${l.boxes.length} boxes</strong><span>${volume} occupied unit cells</span><span>${e.dirty?'Unsaved changes':'Saved'}</span></div><p class="small-copy">Click the ground to add a box. Click an existing box to select it, or add a unit box on top. Large boxes use the dimensions on the right.</p><div class="actions">${button('undo','Undo',e.undo.length?'':'disabled')}${button('redo','Redo',e.redo.length?'':'disabled')}${button('mirror','Mirror')}${button('rotate','Rotate')}${button('clear','Clear')}</div><div class="validation ${errors.length?'invalid':'valid'}" role="status">${errors.length?errors.slice(0,4).map(esc).join('<br>'):'Ready to play. Preview the level to check that every box is distinguishable.'}</div></div><div class="editor-right">${field('level-name','Level name',`<input id="level-name" maxlength="80" value="${esc(l.name)}">`)}<h3>${selected?'Selected box':'New box dimensions'}</h3><div class="properties-grid">${properties}</div><div class="actions">${button('apply-box','Apply to selected',selected?'':'disabled')}${button('stack','Stack a unit box',selected?'':'disabled')}${button('duplicate-box','Duplicate',selected?'':'disabled')}${button('delete-box','Delete selected',selected?'':'disabled')}</div>${field('presentation','Presentation',`<select id="presentation">${options([['static','Stationary'],['travel','Travel across screen']],l.presentation.kind)}</select>`)}${field('view-duration','Viewing or travel duration in ms',`<input id="view-duration" type="number" min="${l.presentation.kind==='travel'?300:100}" max="10000" step="50" value="${l.presentation.durationMs}">`)}${l.presentation.kind==='travel'?field('travel-direction','Travel direction',`<select id="travel-direction">${options([['left','From right to left'],['right','From left to right']],l.presentation.from.x>0?'left':'right')}</select>`):''}<details><summary>Reveal order</summary><ol class="reveal-list">${l.revealOrder.map((id,i)=>`<li><span>${esc(id)}</span><button data-action="reveal-up" data-index="${i}" ${i?'':'disabled'} aria-label="Move ${esc(id)} earlier">↑</button><button data-action="reveal-down" data-index="${i}" ${i<l.revealOrder.length-1?'':'disabled'} aria-label="Move ${esc(id)} later">↓</button></li>`).join('')}</ol></details><div class="actions editor-save">${button('save-level',store.levels.some(s=>s.id===l.id)?'Save changes':'Save level',errors.length?'disabled':'',true)}${button('save-copy','Save as copy',errors.length?'disabled':'')}${button('test-level','Test solo',errors.length?'disabled':'')}${button('test-duel','Test with two',errors.length?'disabled':'')}${button('export-level','Export JSON',errors.length?'disabled':'')}</div><div class="actions">${button('blank-level','New blank level')}${button('random-level','Generate a level')}</div></div></div></div>`};
  }
  if(screen==='library')return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Saved on this browser</p><h2>My levels and packs</h2></div>${button('menu','Back')}</div><div class="actions library-actions">${button('editor','Create a level','',true)}${button('new-pack','Build a pack')}<label class="action file-button">Import JSON<input id="pack-import" type="file" accept=".json,application/json" hidden></label></div><h3>Levels <span class="muted">${store.levels.length}</span></h3>${store.levels.length?store.levels.map(l=>`<div class="library-row"><div><strong>${esc(l.name)}</strong><span>${l.boxes.length} boxes · ${l.presentation.kind==='travel'?'Travelling':'Stationary'} · ${l.presentation.durationMs} ms</span></div><div class="actions">${button('edit-saved','Edit',`data-id="${esc(l.id)}"`)}${button('play-saved','Play',`data-id="${esc(l.id)}"`)}${button('export-saved','Export',`data-id="${esc(l.id)}"`)}${button('delete-saved','Remove',`data-id="${esc(l.id)}"`)}</div></div>`).join(''):'<p class="empty-copy">Create and save a level to start your collection.</p>'}<h3>Packs <span class="muted">${store.packs.length}</span></h3>${store.packs.length?store.packs.map(p=>`<div class="library-row"><div><strong>${esc(p.title)}</strong><span>${p.levels.length} levels</span></div><div class="actions">${button('play-pack','Play pack',`data-id="${esc(p.id)}"`)}${button('edit-pack','Edit',`data-id="${esc(p.id)}"`)}${button('export-pack','Export',`data-id="${esc(p.id)}"`)}${button('delete-pack','Remove',`data-id="${esc(p.id)}"`)}</div></div>`).join(''):'<p class="empty-copy">Build a pack from your levels, or import a version 1 JSON pack.</p>'}</div>`};
  if(screen==='pack-builder'){
    const draft=ui.packDraft;
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Arrange a match</p><h2>Pack builder</h2></div>${button('library','Back')}</div>${field('pack-title','Pack title',`<input id="pack-title" maxlength="80" value="${esc(draft.title)}">`)}<div class="pack-add">${field('pack-add-level','Add a level',`<select id="pack-add-level">${options(availableLevels(ctx).map(l=>[l.key,l.label]),ui.packAddKey??'reference:0')}</select>`)}${button('pack-add','Add')}</div><div class="pack-order">${draft.levels.map((l,i)=>`<div class="library-row"><div><strong>${i+1}. ${esc(l.name)}</strong><span>${l.boxes.length} boxes</span></div><div class="actions">${button('pack-up','↑',`data-index="${i}" ${i?'':'disabled'} aria-label="Move level ${i+1} earlier"`)}${button('pack-down','↓',`data-index="${i}" ${i<draft.levels.length-1?'':'disabled'} aria-label="Move level ${i+1} later"`)}${button('pack-edit-level','Edit copy',`data-index="${i}"`)}${button('pack-remove','Remove',`data-index="${i}"`)}</div></div>`).join('')||'<p class="empty-copy">Add up to 50 levels and put them in the order you want to play.</p>'}</div><div class="actions">${button('save-pack','Save pack',draft.levels.length?'':'disabled',true)}${button('export-draft-pack','Export JSON',draft.levels.length?'':'disabled')}${button('test-pack','Play pack',draft.levels.length?'':'disabled')}</div></div>`};
  }
  if(screen==='history'){
    const history=store.history;
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Your completed sessions</p><h2>Match history</h2></div>${button('menu','Back')}</div><p class="small-copy">The latest 100 sessions are kept locally, within the browser’s storage limit. Replays use the saved arrangements and are marked as practice.</p>${history.length?history.map(h=>`<div class="library-row"><div><strong>${esc(h.label)}${h.assisted?' · assisted':''}</strong><span>${new Date(h.date).toLocaleString()} · ${h.totalRounds??h.rounds.length} rounds · ${h.solo?`${h.summary?.accuracy??soloSummary(h.rounds).accuracy}% correct`:h.summary?.winner===null?'Draw':`Player ${(h.summary?.winner??scoreMatch(h.rounds).winner??0)+1} won`}</span></div><div class="actions">${button('history-detail','Details',`data-id="${esc(h.id)}"`)}${button('replay','Replay practice',`data-id="${esc(h.id)}"`)}</div></div>`).join(''):'<p class="empty-copy">Finish a match or practice session to see it here.</p>'}</div>`};
  }
  if(screen==='details'){
    const record=ui.detailRecord,rounds=record?.rounds??engine.rounds,solo=record?.solo??engine.config.solo;
    return {cls:'active form-screen scroll-screen',html:`<div class="wide-panel"><div class="page-top"><div><p class="eyebrow">Answer by answer</p><h2>Round details</h2></div>${button('details-back','Back')}</div><div class="table-scroll"><table><thead><tr><th>Round</th><th>Boxes</th><th>Player 1</th><th>Time</th>${solo?'':'<th>Player 2</th><th>Time</th>'}</tr></thead><tbody>${rounds.map((r,i)=>`<tr><td>${r.round??i+1}</td><td>${r.answer}</td>${r.players.slice(0,solo?1:2).map(p=>`<td>${p.guess??'No answer'} ${p.guess===r.answer?'✓':'✕'}</td><td>${formatSeconds(p.elapsedMs)}s${!solo&&p.guess!==r.answer?' + 5s':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${record?.totalRounds>rounds.length?'<p class="small-copy">This long practice session keeps details for its latest 50 rounds.</p>':''}</div>`};
  }
  if(screen==='help')return {cls:'active form-screen scroll-screen',html:`<div class="form-panel help-panel"><p class="eyebrow">Every box counts</p><h2>How to play</h2><ol><li><strong>Watch.</strong> After the countdown, remember the separate boxes on the board. Towers count one per box. A large box without internal edges counts as one.</li><li><strong>Count.</strong> When the board disappears, tap your count key once per box. P1 uses <kbd>${esc(keyName(b.p1Count))}</kbd>; P2 uses <kbd>${esc(keyName(b.p2Count))}</kbd>. The counter starts at zero and goes up to 99.</li><li><strong>Lock your answer.</strong> P1 presses <kbd>${esc(keyName(b.p1Submit))}</kbd>; P2 presses <kbd>${esc(keyName(b.p2Submit))}</kbd>. You cannot change a locked answer. Your own timer stops immediately.</li><li><strong>See the reveal.</strong> After everyone submits, each box turns green and the correct total appears. A check means correct; a cross means wrong.</li><li><strong>Win the match.</strong> Your answer times are added together, with five seconds for each mistake. The lower total wins. Equal totals to the displayed hundredth of a second are a draw. Solo practice reports accuracy and average time.</li></ol><h3>Choose your game</h3><p>Classic plays the ten reconstructed reference puzzles. Quick and Full create five or twenty fresh puzzles. Endless is solo practice until you choose Finish practice. Choose a puzzle plays any saved arrangement. Custom lets you choose a pack, round count, viewing time, and optional answer deadline. Missing a deadline counts as a mistake.</p><h3>Pause and accessibility</h3><p>Escape, switching tabs, or losing focus pauses play. An unfinished generated puzzle is replaced when you resume. Authored puzzles restart mirrored and mark the session as assisted. Finished rounds keep their times. Settings lets you remap keys, mute audio, raise contrast, or replace travel with a stationary view.</p><h3>Make and keep puzzles</h3><p>The editor supports separate boxes, large boxes, and supported towers. Save levels, arrange packs, and export JSON backups. Your library and match history are stored in this browser; use exports to move packs to another device. Replays are marked as practice.</p><p class="small-copy">An independent browser recreation of the Box Counting minigame in Dr Kawashima’s Brain Training for Nintendo Switch, based on <a href="https://www.youtube.com/watch?v=2SR6dQM1BDc" target="_blank" rel="noopener">recorded gameplay</a>. Geometry and audio are made for this version. Reconstructed layouts and some timings are approximate.</p><div class="actions">${button('menu','Back to game','',true)}</div></div>`};
  if(screen==='error')return {cls:'active error',html:`<div class="error-panel"><h2>Couldn’t load the game</h2><p>${esc(ui.error)}</p><p>Start the local server and reload this page.</p></div>`};
  return {cls:'',html:''};
}
